<pre><code>&lt;video src="stream.mp4"&gt;

    &lt;!-- Don't support &lt;video&gt; --&gt;
    &lt;object&gt;
        &lt;param name="src" value="video.mp4" /&gt;
             &lt;param name="autoplay" value="true" /&gt;
